# =====================================================================
#  hotel.map - phishing phrases for hotels and hospitality
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake guest complaints (bed bugs, hygiene, sanitary),
#           complaint "evidence" (photo/video), guest left belongings,
#           fake cancellation requests, fake guest messages,
#           OTA account suspension / extranet login (Booking.com,
#           Expedia, Agoda, Airbnb), card / payment problems,
#           channel manager sync errors, complaint-frequency warnings
#
#  Avoided: generic guest questions ("information about my booking"),
#           because real guests write them every day.
# =====================================================================

# ===== English =====
# Fake complaints
/official\s+complaint\s+has\s+been\s+filed\s+by\s+a\s+guest/i
/guest\s+has\s+submitted\s+a\s+complaint\s+regarding\s+(a|their|the)\s+stay/i
/a\s+complaint\s+has\s+been\s+received\s+about\s+your\s+property/i
/formal\s+complaint\s+(received|filed|submitted)/i
/guest\s+complaint\s+#?\d+/i
/reservation\s+complaint\s+notice/i
/bed\s?bugs?\s+(infestation|presence|in\s+(my|the)\s+room|incident)/i
/(guest|visitor)\s+(report|reported|reports)\s*:?\s+(possible\s+)?bed\s?bugs?/i
/review\s+of\s+sanitary\s+conditions/i
/(excessive|high)\s+complaint\s+frequency/i
/more\s+issue\s+reports/i
# Complaint "evidence"
/view\s+(the\s+)?photo\s+(and|&)\s+video\s+evidence/i
/review\s+(the\s+)?(attached\s+)?(photo|video|photo\/video|evidence)\s+within\s+\d+\s+hours/i
/have\s+been\s+compiled\s+for\s+you\s+in\s+an\s+archive/i
/this\s+link\s+is\s+valid\s+for\s+\d+\s+hours/i
/temporary\s+suspension\s+from\s+the\s+platform/i
# Fake complaints / "lost money" lures (2025-08 templates)
/(critical\s+)?guest\s+comments?\s+(was|were|has\s+been|have\s+been)\s+submitted/i
/guest\s+complaint\s+regarding\s+(a\s+|your\s+)?recent\s+stay/i
/view\s+(the\s+)?(guest\s+)?complaint(\s+(&|and)\s+contact\s+(the\s+)?guest)?/i
/guests?\s+(have\s+)?lost\s+money\s+due\s+to\s+technical\s+(failures?|issues?|errors?)/i
/charged\s+(fully|the\s+full\s+amount|in\s+full)\s+(but\s+never\s+received|without\s+(ever\s+)?receiving)\s+(a\s+|any\s+)?confirmation/i
/(that\s+|the\s+)?guest\s+(now\s+)?(plans|intends|is\s+planning)\s+(to\s+take\s+)?legal\s+action/i
/(suspend|disable|pause|hide)\s+(the\s+)?(visibility\s+of\s+your\s+property|your\s+property['’]?s?\s+visibility|showing\s+your\s+property)/i
/(property|listing)\s+(may|will)\s+be\s+(temporarily\s+)?(disabled|suspended|paused|hidden|removed)\s+from\s+the\s+platform/i
/(affected\s+)?guest['’]?s?\s+(booking\s+and\s+)?charge\s+details/i
# Fake sign-in alerts (2025-08 templates)
/sign-?in\s+activity\s+from\s+(an\s+)?(alternate|unknown|new|unrecognized)\s+(setup|device|location)/i
/click\s+the\s+button\s+below\s+to\s+(close|end|terminate)\s+the\s+session/i
/check\s+that\s+your\s+url\s+reads/i

# Lost items
/guest\s+left\s+(personal\s+)?(belongings|items?)\s+(on|at|in)\s+the\s+property/i
/(message|note)\s+from\s+guest\s+about\s+(an\s+)?item\s+left/i
# Fake cancellations
/(your\s+)?guest\s+(has\s+)?requested\s+a\s+cancellation/i
/guest\s+is\s+asking\s+to\s+cancel\s+(their|the)\s+(stay|reservation|booking)/i
/a\s+guest\s+would\s+like\s+to\s+cancel\s+(their|the)\s+(stay|reservation|booking)/i
/review\s+cancellation\s+request\s+from\s+(the\s+)?guest/i
/cancellation\s+transmission\s+error/i
# Fake guest messages / OTA inbox
/you\s+have\s+an\s+unread\s+guest\s+message/i
/new\s+message\s+in\s+your\s+(booking\.com|expedia|agoda|airbnb)\s+inbox/i
/action\s+(needed|required):?\s+(guest\s+sent\s+a\s+note|new\s+guest\s+message|confirm\s+booking)/i
/reminder:?\s+reply\s+to\s+guest/i
/respond\s+within\s+\d+\s*h(ours)?:?\s+guest\s+feedback/i
# OTA account / extranet
/(booking\.com|expedia|agoda|airbnb)\s+(extranet|partner\s+hub|partner\s+central)\s+(account|access)\s+(suspended|restricted|locked|limited)/i
/(unusual|new)\s+(login|session|sign-?in)\s+detected\s+(through|via|within)\s+your\s+(secure\s+session|account|access\s+panel)/i
/sign-?in\s+from\s+unknown\s+device\s+within\s+your/i
/your\s+(property|listing)\s+(will\s+be|has\s+been)\s+(suspended|deactivated|closed|removed|hidden)/i
/channel\s+synchronization\s+failure\s+detected/i
/(rate|availability)\s+sync(hronization)?\s+(error|failed|failure)/i
# Card / payment
/(guest('s)?\s+)?credit\s+card\s+(is\s+)?(invalid|declined|could\s+not\s+be\s+charged)/i
/(update|verify)\s+(your\s+)?(bank|payout|payment)\s+details\s+(to\s+receive|for)\s+(payouts?|payments?)/i
/received\s+a\s+voucher\s+from\s+your\s+guest\s+indicating/i
/we\s+refer\s+to\s+our\s+booking\s+on\s+agoda/i
/see\s+screenshot\s+of\s+the\s+agoda\s+booking\s+information/i

